export const escape = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span aria-hidden="true">↗</span>';
const cta=(text='Request a Quote',href='/rfq',kind='lime')=>`<a class="button ${kind}" href="${href}">${text} ${arrow}</a>`;
const eyebrow=t=>`<p class="eyebrow">${t}</p>`;
const img=(src,alt,cls='',eager=false)=>`<img class="${cls}" src="/assets/${src}" alt="${alt}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async" width="1200" height="1400">`;
const photoHero=(file,alt)=>`<section class="wide-photo authentic-hero">${img('heritage/'+file,alt,'',true)}<span>OUR PEOPLE. OUR FACTORY. CLARK FREEPORT, PHILIPPINES.</span></section>`;
const productCards=()=>products.map(p=>`<a class="product-card" href="/products/${p.slug}"><div class="product-image">${img(p.image,`${p.name} illustrative garment concept`)}<span class="image-arrow">↗</span></div><div class="product-name"><h3>${p.name}</h3><span>↗</span></div><p>${p.summary}</p></a>`).join('');
const faqBlock=()=>`<div class="faq-list">${faqs.map(([q,a],i)=>`<details><summary><span class="faq-number">0${i+1}</span>${q}<span class="plus" aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div>`;
const band=()=>`<section class="closing section-pad"><div>${eyebrow('YOUR NEXT COLLECTION STARTS HERE')}<h2>Let’s make something<br>exceptional.</h2><p>Bring your idea. We’ll help with the next step.</p></div>${cta()}</section>`;
function layout(title,description,body,path='/',noindex=false){
 const origin=(process.env.SITE_URL||'http://localhost:3000').replace(/\/$/,'');
 const organization={'@context':'https://schema.org','@type':'Organization','@id':origin+'/#organization',name:company.name,alternateName:'CSL',foundingDate:'2006',url:origin,logo:origin+'/assets/csl-logo.png',telephone:company.phone,sameAs:['https://www.linkedin.com/company/custom-sports-and-leisure-manufacturing-corp','https://www.facebook.com/CustomSportsAndLeisure/','https://www.instagram.com/customsportsandleisure/'],address:{'@type':'PostalAddress',streetAddress:'Unit 11A3 Philexcel Business Park, M.A. Roxas Highway',addressLocality:'Clark Freeport Zone, Angeles City',addressRegion:'Pampanga',postalCode:'2023',addressCountry:'PH'},description:company.summary,areaServed:'Worldwide',knowsAbout:['Custom sportswear manufacturing','Sublimated teamwear','Corporate apparel','Garment export enquiries']};
 const pageImage=path==='/clark-freeport'?'/assets/philexcel-business-park.webp':path==='/fabrics'?'/assets/heritage/csl-original-01.webp':path==='/capabilities'?'/assets/factory.jpg':path==='/design-gallery'?'/assets/design-renders/rugby.webp':path.startsWith('/products/')?'/assets/'+(products.find(p=>path==='/products/'+p.slug)?.image||'hero.webp'):'/assets/heritage/csl-original-17.webp';
 const schema={'@context':'https://schema.org','@graph':[organization,{'@type':'WebSite','@id':origin+'/#website',name:company.name,url:origin},{'@type':path==='/about'?'AboutPage':path==='/contact'?'ContactPage':path==='/faqs'?'FAQPage':path==='/products'||path==='/industries'||path==='/design-gallery'?'CollectionPage':'WebPage','@id':origin+path+'#webpage',url:origin+path,name:title,description,isPartOf:{'@id':origin+'/#website'},about:{'@id':origin+'/#organization'},inLanguage:'en',dateModified:'2026-10-24',primaryImageOfPage:{'@type':'ImageObject',url:origin+pageImage},...(path==='/faqs'?{mainEntity:faqs.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))}:{})},...(path!=='/'?[{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:origin+'/'},{'@type':'ListItem',position:2,name:title,item:origin+path}]}]:[])]};
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="google-site-verification" content="G5CV3ww0bp23InEYrbFmAh2-zNHDCGCt0qxma1nV4Sw"><meta name="msvalidate.01" content="C467149C93C89FD7BB78443FEA4F7BF9"><meta name="theme-color" content="#c7fa36"><title>${escape(title)} | CSL Manufacturing</title><meta name="description" content="${escape(description)}"><meta name="robots" content="${noindex||process.env.SEARCH_INDEXING!=='true'?'noindex, nofollow':'index, follow, max-image-preview:large'}"><link rel="canonical" href="${escape(origin+path)}"><meta property="og:type" content="website"><meta property="og:title" content="${escape(title)} | CSL Manufacturing"><meta property="og:description" content="${escape(description)}"><meta property="og:url" content="${escape(origin+path)}"><meta property="og:image" content="${escape(origin+pageImage)}"><meta property="og:image:secure_url" content="${escape(origin+pageImage)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escape(title)} | CSL Manufacturing"><meta name="twitter:description" content="${escape(description)}"><meta name="twitter:image" content="${escape(origin+pageImage)}"><meta property="og:image:alt" content="${escape(path==='/clark-freeport'?'Philexcel Business Park entrance, Clark Freeport':path==='/design-gallery'?'Illustrative AI-created sportswear design concepts':path==='/fabrics'?'Original CSL sportswear fabric texture':'CSL people, products and manufacturing in the Philippines')}"><meta name="twitter:image:alt" content="${escape(path==='/fabrics'?'Original CSL sportswear fabric texture':'CSL sportswear and custom apparel manufacturing')}"><meta property="og:image:type" content="${pageImage.endsWith('.webp')?'image/webp':'image/jpeg'}"><meta property="og:locale" content="en_PH"><meta property="og:site_name" content="CSL Manufacturing"><link rel="describedby" href="/llms.txt" type="text/plain"><link rel="alternate" href="/llms-full.txt" type="text/plain" title="CSL company and manufacturing information"><link rel="icon" href="/assets/favicon-32.png" sizes="32x32" type="image/png"><link rel="icon" href="/assets/favicon-192.png" sizes="192x192" type="image/png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><link rel="stylesheet" href="/styles.css?v=1.8.0"><script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script><script src="/app.js?v=1.8.0" defer></script>${path!=='/nexus'&&!noindex?'<script src="/analytics.js?v=1.7.1" defer></script>':''}</head><body><a class="skip-link" href="#main">Skip to content</a>
 <div class="utility-bar"><span>EXPORT-FOCUSED. LOCALLY ROOTED.</span><div><a href="/clark-freeport">Why Clark Freeport</a><a href="/design-gallery">Design Gallery <small>SPORTS + BUSINESS</small></a><a href="/track-order">Track Your Order <small>PHASE 2</small></a></div></div><header class="site-header"><a class="brand" href="/" aria-label="CSL Manufacturing home"><img src="/assets/csl-logo.png" alt="CSL" width="124" height="76"></a><div class="header-center"><p>PHILIPPINE SPORTSWEAR &amp; CUSTOM APPAREL MANUFACTURING. WORLDWIDE EXPORT.</p><nav id="main-nav" aria-label="Main navigation"><a href="/" ${path==='/'?'aria-current="page"':''}>Home</a><a href="/products" ${path.startsWith('/products')?'aria-current="page"':''}>Products</a><a href="/industries" ${path.startsWith('/industries')?'aria-current="page"':''}>Industries</a><a href="/design-gallery" ${path==='/design-gallery'?'aria-current="page"':''}>Design Gallery</a><a href="/capabilities" ${path==='/capabilities'?'aria-current="page"':''}>Capabilities</a><a href="/fabrics" ${path==='/fabrics'?'aria-current="page"':''}>Fabrics</a><a href="/about" ${path==='/about'?'aria-current="page"':''}>Our Story</a><a class="studio-nav" href="/studio" ${path==='/studio'?'aria-current="page"':''}>CSL Studio <span>SOON</span></a><a class="mobile-contact" href="/track-order">Track your Order · Soon</a><a href="/contact" ${path==='/contact'?'aria-current="page"':''}>Contact Us</a></nav></div><a class="header-quote button dark" href="/rfq">Request a Quote <span>↗</span></a><button class="menu-toggle" type="button" aria-label="Open navigation" aria-controls="main-nav" aria-expanded="false"><span></span><span></span></button></header>
 <main id="main">${body}</main><footer class="site-footer section-pad"><div class="footer-top"><a class="footer-brand" href="/"><img src="/assets/csl-logo.png" alt="CSL Manufacturing" width="124" height="76" loading="lazy"><span>Custom Sports & Leisure<br><small>ESTABLISHED 2006 · FAMILY MANUFACTURING HERITAGE SINCE 1988</small></span></a><div><p>Your brand. Our craft.<br>Made in the Philippines.</p><address>${company.address}<br><a href="tel:${company.tel}">${company.phone}</a></address></div><div><a href="/products">Our products</a><a href="/capabilities">Our capabilities</a><a href="/clark-freeport">The Clark Freeport Advantage</a><a href="https://www.linkedin.com/company/custom-sports-and-leisure-manufacturing-corp" target="_blank" rel="noopener">CSL on LinkedIn ↗</a><a href="https://www.facebook.com/CustomSportsAndLeisure/" target="_blank" rel="noopener">Facebook / Follow CSL ↗</a><a href="https://www.instagram.com/customsportsandleisure/" target="_blank" rel="noopener">Instagram / CSL designs ↗</a><a href="/studio">CSL Studio · Coming soon</a></div><div><a href="/rfq">Request a quote</a><a href="/contact">Contact us</a><a href="/faqs">Buyer FAQs</a><a href="/design-gallery">Design Gallery · Concepts</a><a href="/track-order">Track your Order · Coming Soon</a><a href="/privacy">Privacy Policy</a><a href="/terms">Terms of Use</a><a href="/trade-information">Trade &amp; Ordering Information</a></div></div><div class="footer-assistants"><a class="footer-nexus" href="/nexus">✦ ASK NEXUS <small>CSL AI AGENT · INTERNAL</small></a><button type="button" class="button lime" data-open-chat>✦ Ask Mike <span>CSL AI Assistant</span></button></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${company.name}</span><span>Product concept photography is illustrative.</span>${path!=='/nexus'?'<button type="button" class="analytics-settings" data-analytics-settings>Analytics preferences</button>':''}<a href="#main">Back to top ↑</a><a class="powered-by" href="https://axon.com.sg" target="_blank" rel="noopener">Powered by <strong>Axon 1Pro</strong> ↗</a></div></footer>
 <a class="nexus-launcher" href="/nexus"><span>✦ ASK NEXUS</span><small>CSL AI AGENT · INTERNAL</small></a><button class="chat-launcher" type="button" aria-label="Open Mike, CSL AI Assistant" aria-expanded="false" aria-controls="chat-panel"><span class="chat-icon">✦</span><span>Ask Mike</span><span class="online-dot"></span></button><div class="chat-backdrop" hidden></div><section id="chat-panel" class="chat-panel" role="dialog" aria-modal="true" aria-label="Mike, CSL AI Assistant" tabindex="-1" hidden><div class="chat-header"><div><b>Mike <span>✦</span></b><small id="chat-mode">CSL AI Assistant</small></div><button type="button" id="chat-close" aria-label="Close assistant">×</button></div><div class="chat-messages" aria-live="polite" aria-relevant="additions"><p class="chat-message assistant">My name is Mike, CSL AI Assistant. How can I help you today? Tell me what you’d like to make, or ask about CSL.</p></div><div class="chat-suggestions"><button type="button" data-question="What is the minimum order?">Minimum orders</button><button type="button" data-question="Can I upload my logo?">Send a concept</button><button type="button" data-question="What is CSL Studio?">CSL Studio</button></div><form id="chat-form" method="post" action="/api/chat"><label class="sr-only" for="chat-input">Your message</label><input id="chat-input" maxlength="1500" placeholder="Tell us what you have in mind…" required autocomplete="off"><button type="submit" aria-label="Send message">↑</button></form><div id="mike-actions" class="mike-actions" aria-label="Helpful next steps"></div><div class="chat-links"><a href="/rfq">Request a quote ↗</a><a href="/contact">Contact the team ↗</a></div><p class="chat-disclaimer">AI guidance. CSL confirms pricing, approvals and delivery. Requests are sent only when you submit a form or email.</p></section>${path!=='/nexus'&&!noindex?'<section id="analytics-consent" class="analytics-consent" aria-label="Analytics preferences" hidden><p><strong>Help us improve CSL.</strong> Allow Google Analytics to measure visits and successful enquiries. Your form details and artwork are not sent to Analytics. <a href="/privacy">Privacy notice</a></p><div><button class="button dark" type="button" data-analytics-allow>Allow analytics</button><button class="button" type="button" data-analytics-decline>Decline</button></div></section>':''}</body></html>`;
}

function heritageSection(page,title){const images=heritageImages.filter(x=>x.pages.includes(page));const extra=page==='/'?['03']:page==='/history'?['06','11']:page==='/factory'?['03']:page==='/contact'?['06','11']:[];for(const id of extra){const item=heritageImages.find(x=>x.file==='csl-original-'+id+'.webp');if(item&&!images.includes(item))images.push(item);}return `<section class="section-pad heritage-section" ${page==='/fabrics'?'id="fabric-collection"':''}><p class="eyebrow">AUTHENTIC CSL / FROM OUR ORIGINAL WEBSITE</p><h2>${title}</h2><p>Our people, our materials, our manufacturing. Original CSL photography.</p><div class="heritage-grid ${page==='/fabrics'?'swatch-grid':''}">${images.map((x,i)=>`<figure><a ${page==='/fabrics'?'class="fabric-zoom-trigger" data-fabric-original="/assets/fabric-originals/'+x.file.replace('.webp','.jpg')+'" data-fabric-name="'+escape(({'01':'ST Spandex','02':'Triple Play','12':'Taslan','13':'Compression Fabric','14':'CS245','18':'SF6007','19':'Polydex','20':'Mini Waffle','21':'RA240','24':'HP','25':'Ultra 360','26':'Polyblue','27':'XD15'}[x.file.match(/(\d+)\.webp$/)[1]]||x.label))+'"':''} href="/assets/heritage/${x.file}" target="_blank" rel="noopener" aria-label="View ${escape(x.caption||x.label)} full image"><img src="/assets/heritage/${x.file}" alt="${escape(x.caption||x.label)}" loading="lazy" decoding="async" width="1200" height="800"></a><figcaption>${page==='/fabrics'?'<strong>'+escape(({'01':'ST Spandex','02':'Triple Play','12':'Taslan','13':'Compression Fabric','14':'CS245','18':'SF6007','19':'Polydex','20':'Mini Waffle','21':'RA240','24':'HP','25':'Ultra 360','26':'Polyblue','27':'XD15'}[x.file.match(/(\d+)\.webp$/)[1]]||x.label))+'</strong><br>Tap or click to enlarge ↗':escape(x.caption||x.label)}</figcaption></figure>`).join('')}</div></section>`;}
function sportsTeaser(){return `<section class="section-pad sports-home"><div class="section-heading"><div><p class="eyebrow">RUGBY AT HEART. MADE FOR YOUR SPORT.</p><h2>Your team.<br>Your business.<br>Your signature.</h2></div><div><p>Explore 14 sports and 11 business categories, with 12 original concepts in every collection. Rugby, hotels, bars, companies and more.</p><a class="button dark" href="/design-gallery">Explore Sports & Industry Designs ↗</a></div></div><div class="sports-preview">${['Rugby','Football','Basketball'].map((sport,i)=>`<a href="/design-gallery?sport=${encodeURIComponent(sport)}"><div class="jersey-art">${designRender(sport,i)}</div><h3>${sport}</h3><span>Explore 12 concepts ↗</span></a>`).join('')}</div><p class="image-note">Photorealistic AI-created design concepts. Interactive AI generation and custom design tools are coming in Phase 2.</p></section><section class="section-pad phase-hub"><p class="eyebrow">THE NEXT CHAPTER / PHASE 2 COMING SOON</p><h2>More control.<br>From concept to repeat order.</h2><div class="phase-hub-grid">${[['/studio','Design your own / Ask AI','Upload your logo, choose a garment, explore an AI concept and send a manufacturing enquiry.'],['/track-order','Track, review & repeat','Planned verified access to current and past orders, approved artwork and quantity or design change requests. No financial details.'],['/nexus','NEXUS / CSL AI Agent','CSL AI Agent for internal users. Work guidance today, with permission-based Trello and email connections planned.']].map(([u,t,d])=>`<a href="${u}"><span class="coming-pill">COMING SOON</span><h3>${t}</h3><p>${d}</p><span>Explore the preview ↗</span></a>`).join('')}</div></section>`;}


function marketSection(){return `<section class="section-pad export-focus"><div><p class="eyebrow">YOUR PHILIPPINE MANUFACTURING PARTNER</p><h2>Built here.<br>For brands everywhere.</h2></div><div><p>CSL focuses on manufacturing enquiries from international brands, distributors, teams and business buyers. We also welcome Philippine customers seeking custom apparel.</p><p>Share your product brief, quantity and destination. We will discuss specifications, artwork approvals, production feasibility and shipping requirements.</p><a class="button dark" href="/export-manufacturing">For International Buyers ↗</a><a class="text-link" href="/industries">Explore industries we serve ↗</a></div></section>`;}
function industriesPage(){return pageIntro('SPORTS, HOSPITALITY, BUSINESS & COMMUNITY','One manufacturing partner.<br>Many ways to wear your brand.','Custom apparel enquiries for international brands, businesses and organisations, with Philippine customers welcome.')+`<section class="section-pad industry-index"><p class="answer-lead">CSL specialises in custom sportswear, corporate and leisure apparel, knitwear and performance socks. Explore the brief that fits your organisation; garment suitability and production requirements are confirmed by our team.</p><div class="industry-index-grid">${industryGroups.map((g,i)=>`<article><div class="jersey-art">${designRender(i?businessCollections.find(x=>x[1]===g.slug)[0]:'Rugby',i)}</div><p class="eyebrow">0${i+1} / ${g.items.length} BUYER TYPES</p><h2><a href="/industries/${g.slug}">${g.title}</a></h2><p>${g.intro}</p><ul>${g.items.map(x=>`<li>${x}</li>`).join('')}</ul><a class="text-link" href="/industries/${g.slug}">Explore apparel &amp; briefing advice ↗</a></article>`).join('')}</div></section>`+marketSection()+band();}
function industryPage(g){return pageIntro('INDUSTRIES / '+g.title.toUpperCase(),g.title+'<br>Apparel Manufacturing',g.intro)+`<section class="section-pad industry-detail"><div><h2>Who is this for?</h2><ul>${g.items.map(x=>`<li>${x}</li>`).join('')}</ul><h2>What can we discuss?</h2><ul>${g.products.map(x=>`<li>${x}</li>`).join('')}</ul><p>These are enquiry and concept categories. Final product range, minimum quantities, fabric availability and manufacturing feasibility require confirmation.</p></div><div><h2>What should your brief include?</h2><p>${g.brief}</p><p>For export projects, include your destination country, required arrival date and packing requirements. Production timing and shipping are assessed separately. Philippine orders are also welcome.</p><a class="button dark" href="/rfq">Request a Tailored Proposal ↗</a><a class="text-link" href="/design-gallery?sport=${encodeURIComponent(g.slug==='sports-teamwear'?'Rugby':businessCollections.find(x=>x[1]===g.slug)[0])}">Explore 12 design concepts ↗</a></div></section>`+band();}
function exportPage(){return pageIntro('INTERNATIONAL BUYERS / PHILIPPINE MANUFACTURING','A local craft.<br>A global outlook.','CSL prioritises export manufacturing enquiries from international brands, distributors, sports teams and businesses. We also serve the Philippine market.')+`<section class="section-pad export-guide"><h2>How do I start an export manufacturing enquiry?</h2><p>Send the garment type, estimated quantity, size breakdown, artwork or concept, destination country and required delivery date through our RFQ form. CSL reviews your specification before confirming a quotation.</p><div class="process-grid">${[['01','Define the product','Confirm intended use, fabric expectations, design, sizes and decoration.'],['02','Review samples & artwork','Discuss sample requirements, artwork versions and who signs off the specification.'],['03','Agree production details','Confirm quantities, packing, agreed approvals and production timing with the team.'],['04','Plan delivery','Discuss destination, shipping responsibilities, export documentation and arrival requirements.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><h2>Are shipping, duties and customs included?</h2><p>Shipping method, delivery terms, duties, taxes and documentation must be confirmed for each quotation. No automatic duty exemption, certification or fixed delivery time is implied.</p><h2>Can Philippine customers enquire too?</h2><p>Yes. Local businesses, clubs and organisations can submit the same manufacturing brief. Tell us your delivery location and required quantity.</p><a class="button dark" href="/rfq">Send Your Export Brief ↗</a></section>`+band();}

function home(){return `<section class="home-photo-hero">${img('heritage/csl-original-17.webp','The CSL team together on our manufacturing floor in Clark Freeport Zone','',true)}<div class="home-photo-copy">${eyebrow('REAL PEOPLE. PERSONAL COMMITMENT.')}<h1>Your brand.<br>Our craft.</h1><p>Custom sportswear and apparel, made by our team in Clark Freeport, Philippines. Built for international brands, with local enquiries welcome.</p><div class="hero-actions">${cta('Start Your Project','/rfq')}<a class="button outline-light" href="/capabilities">Inside Our Factory ↗</a></div></div></section>
 <div class="trust-band"><span>Established 2006</span><i></i><span>In-house manufacturing</span><i></i><span>Made in the Philippines</span></div>
 ${marketSection()}${sportsTeaser()}<section class="products-section section-pad"><div class="section-heading"><div>${eyebrow('MADE TO BE YOURS')}<h2>Made for your<br class="mobile-break"> next move.</h2></div><div><p>Considered sportswear, knitwear and accessories.<br>Made for teams, brands and organisations.</p><a class="text-link" href="/products">View all products ${arrow}</a></div></div><div class="product-grid">${productCards()}</div><p class="image-note">Product photography presents illustrative concepts. Share your specifications for a tailored proposal.</p></section>
 <section class="craft-section"><div class="craft-image">${img('factory.jpg','Garment production at the CSL factory')}</div><div class="craft-copy">${eyebrow('CRAFT YOU CAN SEE')}<h2>Precision at<br>every stage.</h2><p>From fabric selection to final stitch, thoughtful processes make the difference. Explore the people, capabilities and quality checks behind your next order.</p><a class="text-link" href="/capabilities">Discover our capabilities ${arrow}</a><div class="craft-tags"><span>PRINT</span><span>SEW</span><span>FINISH</span><span>CHECK</span></div></div></section>
 <section class="process-section section-pad"><div class="section-heading"><div>${eyebrow('FROM FIRST IDEA TO FINISHED KIT')}<h2>A clear path.<br>A personal approach.</h2></div><p>You bring the vision. We work through the details together.</p></div><div class="process-grid">${[['01','Share your brief','Tell us what you need, your quantity and destination. Upload your artwork or a rough idea.'],['02','Refine the details','We discuss fabrics, construction, decoration and the quotation with you.'],['03','Approve & produce','Once the specifications and approvals are agreed, your project moves into production.'],['04','Check & deliver','Quality checks and agreed shipping arrangements bring the order together.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>
 <section class="studio-teaser section-pad"><div>${eyebrow('THE NEXT CHAPTER / PHASE 2')}<h2>Your imagination.<br>A new kind of studio.</h2><p>Choose a garment. Upload your logo. Explore an idea with AI.<br>CSL Studio will bring it all together.</p>${cta('Discover CSL Studio','/studio','outline-light')}</div><div class="studio-art" aria-hidden="true"><div class="studio-art-label">CSL / STUDIO</div><div class="shirt-outline"><span>YOUR<br>IDEA<br>HERE.</span></div><span class="floating-chip">✦ AI-assisted concepts</span><span class="coming-pill">COMING SOON</span></div></section>
 ${heritageSection('/','The people behind your next collection.')}<section class="faq-section section-pad"><div>${eyebrow('A LITTLE CLARITY')}<h2>Good questions.<br>Straight answers.</h2><p>Need something more specific?<br><a class="text-link" href="/contact">Talk to our team ${arrow}</a></p></div>${faqBlock()}</section>${band()}`;}
const pageIntro=(label,title,text)=>`<section class="page-intro section-pad">${eyebrow(label)}<h1>${title}</h1><p>${text}</p></section>`;
function formPage(type){const rfq=type==='rfq';return `${pageIntro(rfq?'LET’S MAKE IT HAPPEN':'WE’RE HERE TO HELP',rfq?'Your next project<br>starts here.':'Let’s start a<br>conversation.',rfq?'Tell us what you have in mind. A finished design, a rough sketch or simply an idea — there’s a place to start.':'Have a question about CSL, a product or an upcoming project? Send us a note.')}
 <section class="form-layout section-pad"><aside class="form-aside">${eyebrow(rfq?'YOUR BRIEF. OUR NEXT STEP.':'A PERSONAL CONNECTION')}<h2>${rfq?'A better brief.<br>A better beginning.':'Real people.<br>Thoughtful answers.'}</h2><p>${rfq?'Include your product, approximate quantity, destination and timing. Our team will review the details and follow up.':'Our manufacturing team can help you work through the possibilities.'}</p><div class="contact-detail"><span>CALL OUR TEAM</span><a href="tel:${company.tel}">${company.phone}</a></div><div class="contact-detail"><span>EMAIL OUR TEAM</span><a href="mailto:${escape(publicContactEmail())}">${escape(publicContactEmail())}</a></div><div class="contact-detail"><span>CONNECT WITH CSL</span><a href="https://www.linkedin.com/company/custom-sports-and-leisure-manufacturing-corp" target="_blank" rel="noopener">LinkedIn company page ↗</a><a href="https://www.facebook.com/CustomSportsAndLeisure/" target="_blank" rel="noopener">Facebook / Follow CSL ↗</a><a href="https://www.instagram.com/customsportsandleisure/" target="_blank" rel="noopener">Instagram / CSL designs ↗</a></div><div class="contact-detail"><span>VISIT BY ARRANGEMENT</span><p>${company.address}</p><a href="/clark-freeport">Discover the Clark Freeport advantage ↗</a></div><a class="text-link" href="${rfq?'/contact':'/rfq'}">${rfq?'Just a question? Contact us':'Ready with a brief? Request a quote'} ${arrow}</a><div class="form-helper"><span>✦</span><p>Not sure where to start? Open <button type="button" data-open-chat>Ask Mike</button> for a little guidance.</p></div></aside>
 <form class="enquiry-form" method="post" action="/api/enquiries" data-enquiry="${type}"><div class="form-top"><span>${rfq?'MANUFACTURING RFQ':'GENERAL ENQUIRY'}</span><span>Fields marked * are required</span></div><div class="form-grid"><label>Full name *<input name="name" required maxlength="100" autocomplete="name" placeholder="Your full name"></label><label>Work email *<input name="email" type="email" required maxlength="200" autocomplete="email" placeholder="you@company.com"></label><label>Company ${rfq?'*':''}<input name="company" ${rfq?'required':''} maxlength="150" autocomplete="organization" placeholder="Company or organisation"></label><label>Phone / WhatsApp<input name="phone" type="tel" maxlength="50" autocomplete="tel" placeholder="Include country code"></label>
 ${rfq?`<label>Product range *<select name="product" required><option value="">Select a product</option>${products.map(p=>`<option>${p.name}</option>`).join('')}<option>Multiple products</option><option>Other / help me choose</option></select></label><label>Estimated quantity *<input name="quantity" type="number" min="1" max="1000000" required placeholder="Approximate number of pieces"></label><label>Delivery country *<input name="country" required maxlength="100" autocomplete="country-name" placeholder="Where is your order going?"></label><label>Preferred delivery date<input name="deliveryDate" type="date"><small>Our team will confirm feasibility.</small></label><label>Sport / intended use<select name="sport"><option value="">Select a sport or use</option>${[...sports,...businessCollections.map(x=>x[0])].map(x=>`<option>${x}</option>`).join('')}<option>Corporate / leisure</option><option>Other</option></select></label><label>Industry / organisation<select name="industry"><option value="">Select your industry</option>${industryGroups.map(g=>`<option>${g.title}</option>`).join('')}<option>Other</option></select></label><label>Order type<select name="orderType"><option>New design / first order</option><option>Sample / prototype enquiry</option><option>Revised artwork / sample</option><option>Repeat — same design</option><option>Repeat — quantity / sizes change</option><option>Repeat — design change</option></select></label><label>Original order / PO reference<input name="orderReference" maxlength="100" placeholder="If repeating or changing an order"><small>Helps our team find your project; does not grant order access.</small></label><label>Timing<select name="urgency"><option>Standard / flexible</option><option>Event date / fixed deadline</option><option>Urgent — feasibility check needed</option></select></label><label class="span-two">What best describes you?<select name="buyerType"><option value="">Select if applicable</option><option>Brand / distributor</option><option>Sports club / team</option><option>Corporate / organisation</option><option>Other</option></select></label>`:`<label class="span-two">Enquiry subject *<select name="subject" required><option value="">How can we help?</option><option>Product information</option><option>Existing order</option><option>Manufacturing partnership</option><option>CSL Studio interest</option><option>Factory visit</option><option>Other enquiry</option></select></label>`}
 <label class="span-two">${rfq?'Tell us about your project':'Your message'} *<textarea name="message" required minlength="10" maxlength="6000" rows="5" placeholder="${rfq?'Product, colours, sizes, artwork, personalisation and any details that matter…':'Tell us how we can help…'}"></textarea></label></div>
 <div class="upload-zone"><div class="upload-icon" aria-hidden="true">↑</div><strong>Add your artwork or inspiration</strong><p>Logo, reference images, sketches or a concept PDF.</p><label class="upload-button">Choose files<input class="file-input" name="artwork" type="file" accept="image/jpeg,image/png,image/webp,application/pdf,.jpg,.jpeg,.png,.webp,.pdf" multiple></label><small>JPG, PNG, WebP or PDF · Up to 3 files · 5 MB each</small><ul class="file-list" aria-live="polite"></ul></div><label class="honey" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent"><input type="checkbox" name="consent" required><span>I agree that CSL may use my details and uploaded files to respond to this enquiry. I have permission to share these files. Read our <a href="/privacy">privacy notice</a>. *</span></label><button type="submit" class="button dark submit-button">${rfq?'Send My RFQ':'Send Enquiry'} <span>↗</span></button><p class="form-status" role="status" aria-live="polite"></p><p class="form-fineprint">Your enquiry and files are stored privately for review. A quotation is confirmed by the CSL team.</p><noscript><p>Please enable JavaScript to submit files, or call <a href="tel:${company.tel}">${company.phone}</a>.</p></noscript></form></section>`;}
function contactMap(){return `<section class="contact-location section-pad"><div><p class="eyebrow">VISIT CSL / CLARK FREEPORT</p><h1>Let’s connect.<br>Find us in Clark.</h1><address>${company.address}</address><div class="hero-contact-links"><a href="tel:${company.tel}">Call ${company.phone} ↗</a><a href="mailto:${escape(publicContactEmail())}">${escape(publicContactEmail())} ↗</a><a href="https://www.linkedin.com/company/custom-sports-and-leisure-manufacturing-corp" target="_blank" rel="noopener">LinkedIn / Follow CSL ↗</a><a href="https://www.facebook.com/CustomSportsAndLeisure/" target="_blank" rel="noopener">Facebook / Follow CSL ↗</a><a href="https://www.instagram.com/customsportsandleisure/" target="_blank" rel="noopener">Instagram / CSL designs ↗</a></div><p>Factory visits are by prior arrangement. Please contact us to confirm your appointment and meeting point.</p><a class="button lime" href="https://www.google.com/maps/@?api=1&amp;map_action=pano&amp;pano=aqLiJjX4K_NE6vHifCakrw&amp;heading=147.69229" target="_blank" rel="noopener">Open Fullscreen Street View ↗</a></div><div class="street-view-panel"><p class="eyebrow">GOOGLE STREET VIEW / CSL LOCATION</p><div class="map-shell" id="factory-map"><iframe title="Google Street View at the CSL location, May 2024" src="https://www.google.com/maps/embed?pb=!4v1792802390558!6m8!1m7!1saqLiJjX4K_NE6vHifCakrw!2m2!1d15.17246968545677!2d120.5279783131798!3f147.69229!4f0!5f0.7820865974627469" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><p class="map-note">Drag to look around. Use the arrows to explore. Google imagery, May 2024; surroundings may have changed.</p></div></section>`;}

function clarkPage(){return pageIntro('OUR LOCATION / YOUR MANUFACTURING ADVANTAGE','Made in Clark.<br>Connected to the world.','A skilled team in an established Philippine business zone, with international connectivity on our doorstep.')+`<figure class="location-hero">${img('philexcel-business-park.webp','Entrance of Philexcel Business Park in Clark Freeport Zone','',true)}<figcaption>PHILEXCEL BUSINESS PARK / OUR HOME IN CLARK FREEPORT <a href="https://philexcel.com.ph/" target="_blank" rel="noopener">Image: Philexcel Business Park ↗</a></figcaption></figure>`+`<section class="section-pad clark-intro"><p class="eyebrow">WHY LOCATION MATTERS</p><h2>Local craftsmanship.<br>International perspective.</h2><p class="answer-lead">CSL manufactures at Philexcel Business Park in Clark Freeport Zone, Pampanga. Clark combines an international airport, expressway connections and an established business community. For apparel buyers, that provides a practical setting for discussing production, visits and export logistics with one manufacturing team.</p><div class="clark-benefits"><article><span>01 / CONNECTIVITY</span><h3>An international gateway.</h3><p>Clark International Airport connects the region with international passenger and air-cargo networks. Sample dispatch, buyer visits and shipment options can be planned around your project.</p></article><article><span>02 / ROAD NETWORKS</span><h3>Connected across Luzon.</h3><p>SCTEX and links to NLEX connect Clark with major economic centres. Your freight route, carrier and destination are assessed when we prepare the delivery plan.</p></article><article><span>03 / BUSINESS ECOSYSTEM</span><h3>An established industrial setting.</h3><p>Clark brings together manufacturing, logistics and supporting businesses within planned industrial districts. CSL’s factory is part of this wider business environment.</p></article><article><span>04 / PEOPLE</span><h3>Regional talent. Personal care.</h3><p>Clark’s established workforce supports its industrial community. At CSL, the advantage becomes personal: people working through your brief, artwork and production details.</p></article></div></section><section class="section-pad quality-band"><div><p class="eyebrow">WHAT THIS MEANS FOR YOUR PROJECT</p><h2>A clear starting point<br>for export enquiries.</h2></div><div><p>Bring your garment brief, quantity, destination and required arrival date. We will review construction, materials, sample requirements, approvals, packing and shipping responsibilities with you.</p><p>Our primary focus is worldwide export. Philippine businesses, clubs and organisations are also welcome.</p><a class="button lime" href="/rfq">Discuss Your Manufacturing Project ↗</a></div></section><section class="section-pad standalone-faq"><h2>Questions about manufacturing in Clark.</h2><div class="faq-list"><details><summary>Where is CSL located?<span>+</span></summary><p>${company.address}. Visits are by arrangement; contact our team before travelling.</p></details><details><summary>Does Freeport location make every order duty-free?<span>+</span></summary><p>No blanket exemption is promised. Import duties, taxes, origin rules, product classification and delivery terms depend on the destination and the specific transaction. Confirm the applicable arrangements with CSL and your customs adviser before ordering.</p></details><details><summary>Does the location guarantee faster delivery?<span>+</span></summary><p>Connectivity helps us discuss practical shipping options. Production and transit times still depend on the approved specification, quantity, capacity, carrier and customs process. We confirm timing for each project.</p></details><details><summary>Can international buyers visit the factory?<span>+</span></summary><p>Contact us to discuss a visit, your objectives and a suitable appointment. We can confirm our location and meeting arrangements before you travel.</p></details></div><div class="location-sources"><p class="eyebrow">LOCATION REFERENCES / REVIEWED OCTOBER 2026</p><p>Regional connectivity and business-zone context: <a href="https://lec.philippines.business/economic-zones/cdc" target="_blank" rel="noopener">Clark Development Corporation profile ↗</a> and <a href="https://lec.philippines.business/economic-zones/ciac" target="_blank" rel="noopener">Clark International Airport Corporation profile ↗</a>. These describe the region; they do not certify CSL’s eligibility for incentives.</p></div></section>`+band();}

function studio(){return `${pageIntro('CSL STUDIO / PHASE 2','Your ideas.<br>More possibilities.','A new space to imagine, personalise and start your next manufacturing enquiry.')}<section class="studio-coming section-pad"><div class="studio-message"><span class="coming-pill">COMING SOON</span><h2>From “what if”<br>to “let’s make it”.</h2><p>We’re planning a design workspace that brings garment selection, your own artwork and AI-assisted ideas into one experience.</p><p class="muted">CSL Studio is in the Phase 2 roadmap. Design tools and AI image generation are not available yet.</p>${cta('Send Your Concept Today','/rfq')}</div><div class="studio-art large" aria-hidden="true"><div class="studio-art-label">CSL / STUDIO</div><div class="shirt-outline"><span>MAKE<br>IT<br>YOURS.</span></div><span class="floating-chip">✦ Your creative starting point</span></div></section><section class="section-pad studio-roadmap">${eyebrow('THE PLANNED EXPERIENCE')}<h2>One studio. Your creative journey.</h2><div class="process-grid">${[['01','Choose your canvas','Explore T-shirt and garment ranges as the starting point for your design.'],['02','Bring your identity','Upload your logo, colour palette, graphics or reference images.'],['03','Explore with AI','Describe an idea to the assistant or use planned placement and design tools.'],['04','Send it to CSL','Attach your concept and project details to a manufacturing enquiry.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div><p class="roadmap-note">Planned scope, subject to development. Concepts will require artwork and manufacturing review before production.</p></section>${band()}`;}
export const paths=['/','/products',...products.map(p=>'/products/'+p.slug),'/capabilities','/fabrics','/about','/studio','/rfq','/contact','/faqs','/privacy','/terms','/trade-information','/design-gallery','/track-order','/industries','/clark-freeport','/export-manufacturing',...industryGroups.map(g=>'/industries/'+g.slug)];
export function render(path){
 let title,description,body,status=200;
 const policy=legalPage(path,escape(publicContactEmail()));
 if(policy){title=policy.title;description=policy.description;body=policy.body;}
 else if(path==='/'){title='Philippines Sportswear & Apparel Manufacturer for Export';description=company.summary;body=home();}
 else if(path==='/industries'){title='Industries We Serve — Sports, Hospitality & Business Apparel';description='Custom apparel enquiries for sports teams, hotels, bars, companies, manufacturers, schools and events. Export-focused Philippine manufacturing.';body=industriesPage();}
 else if(path.startsWith('/industries/')&&industryGroups.some(g=>path==='/industries/'+g.slug)){const g=industryGroups.find(g=>path==='/industries/'+g.slug);title=g.title+' Apparel Manufacturer in the Philippines';description=g.intro;body=industryPage(g);}
 else if(path==='/clark-freeport'){title='The Clark Freeport Advantage for Apparel Buyers';description='Why CSL manufactures in Clark Freeport Zone: international airport access, expressway connections, established industry and a skilled regional workforce.';body=clarkPage();}
 else if(path==='/export-manufacturing'){title='Philippine Apparel Manufacturing for International Buyers';description='Start an export manufacturing enquiry with CSL: custom sportswear and apparel, specifications, artwork approvals and shipping requirements. Local Philippine buyers welcome.';body=exportPage();}
 else if(path==='/products'){title='Custom Sportswear, Knitwear & Performance Socks';description='Explore CSL manufacturing for sublimated teamwear, corporate apparel, knitwear and performance socks.';body=pageIntro('THE CSL COLLECTION','A range of possibilities.<br>One manufacturing partner.','Explore our product families, then share your own design direction.')+`<section class="section-pad"><div class="product-grid">${productCards()}</div><p class="image-note">Illustrative product concepts. Final specifications are agreed with the CSL team.</p><div class="range-brief"><h2>Build a coordinated collection.</h2><p>Discuss jerseys, reversible teamwear, training tops, shorts, sports trousers, polos, jackets and knit accessories. Tell us which pieces belong together, your size run and decoration requirements. Sample availability and final manufacturing suitability are confirmed by CSL.</p><a class="button dark" href="/rfq">Discuss Your Range or Sample ↗</a></div></section>`+band();}
 else if(path.startsWith('/products/')&&products.some(p=>path==='/products/'+p.slug)){const p=products.find(p=>path==='/products/'+p.slug);title=p.name+' Manufacturing';description=p.text;body=`<section class="product-detail"><div class="product-detail-image">${img(p.image,p.name+' illustrative concept','',true)}<span class="photo-credit">ILLUSTRATIVE PRODUCT CONCEPT</span></div><div class="product-detail-copy">${eyebrow(p.label)}<h1>${p.name}</h1><p class="lead">${p.summary}</p><p>${p.text}</p><ul class="feature-list">${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><p class="muted">Minimum quantities, pricing and lead times are confirmed against your project brief.</p>${cta('Enquire About This Range','/rfq?product='+encodeURIComponent(p.name))}<a class="text-link" href="/fabrics">Explore fabrics ${arrow}</a></div></section>`+band();}
 else if(path==='/gallery'||path==='/design-gallery'){path='/design-gallery';title='Sportswear & Uniform Design Gallery';description='Explore 12 concepts per sport or business category: rugby, hotel uniforms, restaurant and bar apparel, corporate polos and workwear. CSL Studio AI tools coming soon.';body=galleryPage();}
 else if(path==='/track-order'){title='Track Your Order — Coming Soon';description='Phase 2: verified customer access to progress, approved artwork, order history and repeat requests.';body=trackingPage();}
 else if(path==='/nexus'){title='NEXUS — CSL AI Agent for Internal Use';description='NEXUS, the CSL AI Agent for authorised internal users. Work guidance and draft support, with permission-based email and Trello integrations planned.';body=nexusPage();}
 else if(path==='/studio'){title='CSL Studio — Coming Soon';description='Phase 2: planned AI-assisted garment concepts, logo uploads and design tools for your next CSL enquiry.';body=studio();}
 else if(path==='/rfq'||path==='/contact'){title=path==='/rfq'?'Request a Custom Apparel Manufacturing Quote':'Contact CSL — Clark Freeport, Philippines';description='Send your manufacturing enquiry, artwork or concept to the CSL team in the Philippines.';body=(path==='/contact'?contactMap():'')+formPage(path.slice(1))+(path==='/contact'?heritageSection('/contact','Craft, care and a personal connection.'): '');}
 else if(path==='/capabilities'){title='Manufacturing Capabilities & Quality';description='Explore CSL sublimation, sewing, embroidery, knitting and garment quality-control processes.';body=pageIntro('THE PEOPLE. THE PROCESS. THE CRAFT.','Made with purpose.<br>Checked with care.','The details behind your next garment matter. Explore how we bring them together.')+`<section class="wide-photo">${img('factory.jpg','CSL garment factory')}</section><section class="section-pad capability-grid">${capabilities.map(([t,p],i)=>`<article><span class="eyebrow">0${i+1}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</section><section class="quality-band section-pad"><div>${eyebrow('QUALITY IS A PROCESS')}<h2>Care at every handover.</h2></div><p>Fabric checks. Sizing checks. Print inspection. In-line sewing checks. Final garment inspection and packing records. Our production process is built around checking the details along the way.</p></section>`+heritageSection('/factory','Inside the CSL factory.')+band();}
 else if(path==='/fabrics'){title='Sportswear Fabrics & Material Selection';description='Discuss fabric composition, GSM, stretch and intended use with CSL for custom sportswear.';body=pageIntro('THE FOUNDATION OF A GOOD GARMENT','Feel the difference.<br>Choose with purpose.','The right fabric starts with how a garment will be worn.')+'<div class="fabric-jump"><a class="button lime" href="#fabric-collection">View all 13 original fabric photos ↓</a><p>Compression Fabric, CS245, HP, Mini Waffle, Polyblue, Polydex, RA240, SF6007, ST Spandex, Taslan, Triple Play, Ultra 360 and XD15.</p></div>'+`<section class="fabric-layout section-pad"><div class="fabric-visual">${img('rugby.webp','Illustrative close view of a navy and cream rugby garment')}<span>TEXTURE / WEIGHT / MOVEMENT</span></div><div><h2>Start with the performance you need.</h2><p>Our fabric range includes different weights, compositions and stretch characteristics. Tell us about your sport, climate, fit and decoration requirements so we can help select suitable options.</p><div class="fabric-rows">${[['Composition','Polyester and stretch blends, depending on the fabric.'],['Weight','GSM helps compare the weight of a material.'],['Movement','Stretch and construction affect fit and comfort.'],['Recycled options','Ask which recycled fabrics are suitable and what supporting documentation is available.']].map(([t,p])=>`<div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${cta('Discuss Fabrics','/rfq')}</div></section>`+heritageSection('/fabrics','Explore our original fabric collection.')+band();}
 else if(path==='/about'){title='CSL History — Established 2006 in the Philippines';description='Meet CSL, a second-generation family-owned garment manufacturing business in the Philippines.';body=pageIntro('CUSTOM SPORTS & LEISURE','A family business.<br>A shared commitment.','Manufacturing is personal when your family name stands behind the work.')+`<section class="about-layout section-pad"><div>${img('factory.jpg','Inside the CSL factory')}</div><div>${eyebrow('OUR STORY')}<h2>Built through experience.<br>Carried forward with care.</h2><p>CSL is an independent, second-generation family business based in the Philippines. CSL was established in 2006 by Peter and Melody Clark. Our family’s Philippine manufacturing heritage began in 1988 with an earlier golf-bag business. Today, CSL focuses on custom sportswear, knitwear and accessories.</p><p>We believe good manufacturing starts with understanding the brief and staying connected through the details. From product requirements to approvals and production, our team works with you to establish a clear path forward.</p><p>Our factory is located in Clark Freeport Zone, Pampanga. Factory visits can be discussed with the team in advance.</p>${cta('Meet Your Manufacturing Partner','/contact')}</div></section>`+`<section class="section-pad profile-showcase"><p class="eyebrow">CSL / COMPANY PROFILE</p><h2>Sport is part of our story.</h2><img src="/assets/csl-linkedin-cover.jpg" alt="Sportswear imagery published on the CSL LinkedIn company profile" width="1128" height="191" loading="lazy"><p>Sportswear imagery from <a href="https://www.linkedin.com/company/custom-sports-and-leisure-manufacturing-corp" target="_blank" rel="noopener">CSL’s public LinkedIn company profile ↗</a>.</p><a class="button dark" href="/clark-freeport">Why we manufacture in Clark Freeport ↗</a></section>`+heritageSection('/history','A story made by people.')+band();}
 else if(path==='/faqs'){title='Manufacturing & Ordering FAQs';description='Answers about CSL products, minimum quantities, lead times, artwork uploads and manufacturing enquiries.';body=pageIntro('BEFORE YOUR FIRST ORDER','A little clarity<br>goes a long way.','Answers to common questions about working with CSL.')+`<section class="section-pad standalone-faq">${faqBlock()}</section>`+band();}
 else if(path==='/privacy'){title='Enquiry Privacy Notice';description='How CSL handles website enquiries, uploaded artwork and assistant messages.';body=pageIntro('YOUR INFORMATION','Privacy Policy','How information submitted through this website is handled.')+`<article class="prose section-pad"><h2>Who receives your information</h2><p>${company.name}, at ${company.address}, receives enquiries submitted through this website. Call ${company.phone} for privacy questions.</p><h2>What we collect and why</h2><p>When you submit a form, we collect the details you provide and any uploaded artwork to assess your request, prepare a response and discuss potential manufacturing work. Required fields are marked. Please share only information and artwork you are authorised to provide.</p><h2>Artwork and storage</h2><p>Enquiry records and uploaded files are held in private server storage and are not published on this website. Authorised staff can access them for enquiry review. Production hosting is planned in Germany, so submissions may be transferred outside your country.</p><h2>The CSL assistant</h2><p>The assistant provides guidance and does not confirm prices, availability or delivery. If AI answers are enabled, your recent chat messages are sent to the configured AI provider (Groq or OpenAI) to generate a response. Form uploads are not sent to the assistant. Avoid sending sensitive personal information in chat. The assistant identifies whether it is providing guided or AI-assisted answers.</p><h2>Retention and your choices</h2><p>Enquiries are retained while they are needed to handle the request and related business records. Contact CSL to request access, correction or deletion, subject to applicable record-keeping requirements. No marketing subscription is created by submitting an enquiry.</p><h2>Google Maps</h2><p>The Contact page embeds Google Street View. Google receives connection information when that page is loaded and may process data under its own privacy terms. Street View coverage and image dates are controlled by Google.</p><h2>Cookies and analytics</h2><p>Google Analytics4 (G-BFEGVT265Y) measures visits and successful enquiry submissions only after you allow analytics. No advertising features are enabled. Names, email addresses, messages, artwork and order references are not included in our Analytics events. Your choice is stored in this browser; use Analytics preferences in the footer to change it. Chat history stays in the current page session. If you choose Prepare an enquiry, your recent questions are placed in a draft Contact form using temporary browser session storage; review and submit it yourself. The internal NEXUS workspace uses an essential, time-limited authentication cookie when a staff member signs in. Mailtrap may process notification emails when configured; customer login emails are planned for Phase 2. Standard server logs may be retained for operation and security.</p></article>`;}
 else {status=404;title='Page Not Found';description='Find your way back to CSL Manufacturing.';body=pageIntro('404 / A SMALL DETOUR','Let’s get you<br>back on track.','The page you’re looking for isn’t here.')+`<section class="section-pad">${cta('Back to CSL','/')}</section>`;}
 if(path==='/contact')body=body.replace(/(<section class="page-intro[\s\S]*?)<h1>([\s\S]*?)<\/h1>/,'$1<h2>$2</h2>');
 const heroFiles={'/products':'22','/industries':'17','/design-gallery':'05','/export-manufacturing':'22','/about':'17','/fabrics':'01','/studio':'05','/rfq':'16','/faqs':'15','/track-order':'28'};
 const heroId=heroFiles[path]||(path.startsWith('/industries/')?'22':null);
 if(heroId)body=body.replace(/(<section class="page-intro[\s\S]*?<\/section>)/,'$1'+photoHero('csl-original-'+heroId+'.webp',heroId==='17'?'The CSL team at our Clark Freeport manufacturing facility':heroId==='01'?'Original CSL fabric texture swatch':heroId==='05'?'Colour and print planning at CSL':heroId==='16'?'Detailed garment work at the CSL factory':'Original CSL manufacturing photography'));
 return {status,html:layout(title,description,body,path,status===404||path==='/nexus')};
}
